import{_ as t,o as h,c as i,a2 as a}from"./chunks/framework.mRCPFc5l.js";const s=JSON.parse('{"title":"Demo: IB dạy inquiry như thế nào","description":"","frontmatter":{},"headers":[],"relativePath":"ideas/inquiry-ib/index.md","filePath":"ideas/inquiry-ib/index.md"}'),o={name:"ideas/inquiry-ib/index.md"};function c(e,n,r,u,g,m){return h(),i("div",null,[...n[0]||(n[0]=[a('<h1 id="demo-ib-day-inquiry-nhu-the-nao" tabindex="-1">Demo: IB dạy inquiry như thế nào <a class="header-anchor" href="#demo-ib-day-inquiry-nhu-the-nao" aria-label="Permalink to &quot;Demo: IB dạy inquiry như thế nào&quot;">​</a></h1><p>Trên trang này# Demo: IB dạy inquiry như thế nào <a href="#demo-ib-day-inquiry-nhu-the-nao">​</a> Nhóm này là phần <strong>xem tận mắt</strong>. Mỗi môn có ba bài học được viết ra đầy đủ theo đúng khung IB — từ câu hỏi mở đầu, tới từng câu thầy cô nói, tới cách chấm. Mục đích không phải để bạn dạy theo. Mục đích là để bạn <strong>thấy được cái khác biệt</strong> — vì &quot;inquiry-based learning&quot; nghe rất trừu tượng cho tới khi nhìn thấy một tiết học thật diễn ra thế nào. <a href="/ideas/inquiry-ib/toan"><strong>Toán</strong>Số vô tỉ · Hàm số bậc hai · Xác suất và trực giác sai</a><a href="/ideas/inquiry-ib/vat-ly"><strong>Vật lý</strong>Ma sát · Định luật III Newton · Chuyển hoá năng lượng</a><a href="/ideas/inquiry-ib/hoa-hoc"><strong>Hoá học</strong>Bảo toàn khối lượng · Tốc độ phản ứng · Axit–bazơ</a><a href="/ideas/inquiry-ib/sinh-hoc"><strong>Sinh học</strong>Khuếch tán và thẩm thấu · Quang hợp · Chọn lọc tự nhiên</a><a href="/ideas/inquiry-ib/ngu-van"><strong>Ngữ văn</strong>Điểm nhìn kể chuyện · Ẩn dụ · Văn bản và bối cảnh</a><a href="/ideas/inquiry-ib/tieng-anh"><strong>Tiếng Anh</strong>Thì hiện tại hoàn thành · Ngữ vực · Đọc suy luận</a><a href="/ideas/inquiry-ib/lich-su-dia-ly"><strong>Lịch sử · Địa lý</strong>Nguồn sử liệu · Đô thị hoá · Nhân quả trong lịch sử</a><a href="/ideas/inquiry-ib/nghe-thuat-thiet-ke"><strong>Nghệ thuật · Thiết kế</strong>Bố cục · Thiết kế cho người dùng thật · Âm nhạc và cảm xúc</a></p><h2 id="moi-mon-mo-đau-bang-y-lon-nhat-cua-no-​" tabindex="-1">Mỗi môn mở đầu bằng ý lớn nhất của nó <a href="#moi-mon-mo-đau-bang-y-lon-nhat-cua-no">​</a> <a class="header-anchor" href="#moi-mon-mo-đau-bang-y-lon-nhat-cua-no-​" aria-label="Permalink to &quot;Mỗi môn mở đầu bằng ý lớn nhất của nó [​](#moi-mon-mo-đau-bang-y-lon-nhat-cua-no)&quot;">​</a></h2><p>Trước các demo, mỗi trang môn đóng khung <strong>một ý duy nhất xuyên suốt cả môn</strong> — thứ mà nếu learner chỉ mang được một điều ra khỏi môn học đó, nên là điều này. Bên dưới là vài ý cũng quan trọng, nhưng cố ý <strong>không</strong> đặt ngang hàng. Việc phân biệt đó là có chủ đích: một môn học mà mọi thứ đều &quot;quan trọng như nhau&quot; thì không có gì thật sự quan trọng, và learner không có chỗ nào để bám khi quên chi tiết.</p><h2 id="khung-ib-dung-đe-dung-mot-bai-hoc-​" tabindex="-1">Khung IB dùng để dựng một bài học <a href="#khung-ib-dung-đe-dung-mot-bai-hoc">​</a> <a class="header-anchor" href="#khung-ib-dung-đe-dung-mot-bai-hoc-​" aria-label="Permalink to &quot;Khung IB dùng để dựng một bài học [​](#khung-ib-dung-đe-dung-mot-bai-hoc)&quot;">​</a></h2><p>Mọi demo trong nhóm này đều theo cùng một bộ khung. Hiểu bộ khung này thì đọc demo nào cũng nhanh.</p><h3 id="key-concept-—-khai-niem-lon-​" tabindex="-1">Key Concept — khái niệm lớn <a href="#key-concept-—-khai-niem-lon">​</a> <a class="header-anchor" href="#key-concept-—-khai-niem-lon-​" aria-label="Permalink to &quot;Key Concept — khái niệm lớn [​](#key-concept-—-khai-niem-lon)&quot;">​</a></h3><p>IB có 16 khái niệm lớn dùng chung cho mọi môn: <em>Change, Systems, Relationships, Form, Logic, Perspective, Communication, Identity, Creativity, Culture, Connections, Communities, Development, Time-place-space, Global interactions, Aesthetics.</em> Mỗi bài học gắn vào một khái niệm lớn. Đây là lý do học sinh IB nối được kiến thức giữa các môn: &quot;Systems&quot; trong Sinh học và &quot;Systems&quot; trong Kinh tế là cùng một cách nghĩ áp vào hai nội dung.</p><h3 id="related-concepts-—-khai-niem-rieng-cua-mon-​" tabindex="-1">Related Concepts — khái niệm riêng của môn <a href="#related-concepts-—-khai-niem-rieng-cua-mon">​</a> <a class="header-anchor" href="#related-concepts-—-khai-niem-rieng-cua-mon-​" aria-label="Permalink to &quot;Related Concepts — khái niệm riêng của môn [​](#related-concepts-—-khai-niem-rieng-cua-mon)&quot;">​</a></h3><p>Cụ thể hơn, thuộc về môn đó: <em>pattern</em> và <em>equivalence</em> trong Toán, <em>function</em> và <em>transformation</em> trong Sinh, <em>point of view</em> và <em>theme</em> trong Văn.</p><h3 id="global-context-—-bai-nay-lien-quan-gi-toi-the-gioi-​" tabindex="-1">Global Context — bài này liên quan gì tới thế giới <a href="#global-context-—-bai-nay-lien-quan-gi-toi-the-gioi">​</a> <a class="header-anchor" href="#global-context-—-bai-nay-lien-quan-gi-toi-the-gioi-​" aria-label="Permalink to &quot;Global Context — bài này liên quan gì tới thế giới [​](#global-context-—-bai-nay-lien-quan-gi-toi-the-gioi)&quot;">​</a></h3><p>Sáu bối cảnh: bản sắc và quan hệ · định vị trong không gian và thời gian · biểu đạt cá nhân và văn hoá · đổi mới khoa học kỹ thuật · toàn cầu hoá và bền vững · công bằng và phát triển. Đây là câu trả lời có cấu trúc cho câu hỏi &quot;học cái này để làm gì&quot;.</p><h3 id="statement-of-inquiry-—-cau-chot-cua-ca-bai-​" tabindex="-1">Statement of Inquiry — câu chốt của cả bài <a href="#statement-of-inquiry-—-cau-chot-cua-ca-bai">​</a> <a class="header-anchor" href="#statement-of-inquiry-—-cau-chot-cua-ca-bai-​" aria-label="Permalink to &quot;Statement of Inquiry — câu chốt của cả bài [​](#statement-of-inquiry-—-cau-chot-cua-ca-bai)&quot;">​</a></h3><p>Một câu duy nhất, ghép khái niệm lớn với bối cảnh. Ví dụ: <em>&quot;Các hệ thống trong tự nhiên duy trì cân bằng thông qua những dòng chảy mà ta không nhìn thấy trực tiếp.&quot;</em> Câu này được viết lên bảng từ đầu buổi và được quay lại ở cuối.</p><h3 id="ba-loai-cau-hoi-​" tabindex="-1">Ba loại câu hỏi <a href="#ba-loai-cau-hoi">​</a> <a class="header-anchor" href="#ba-loai-cau-hoi-​" aria-label="Permalink to &quot;Ba loại câu hỏi [​](#ba-loai-cau-hoi)&quot;">​</a></h3><p>Đây là phần thực tế nhất, và là thứ bạn có thể mượn ngay tối nay: LoạiĐặc điểmVí dụ (Sinh học)<strong>Factual</strong>Có đáp án đúng, tra đượcKhuếch tán là gì?<strong>Conceptual</strong>Đòi hỏi hiểu và nối, không tra đượcVì sao chất di chuyển mà không cần năng lượng?<strong>Debatable</strong>Có nhiều câu trả lời hợp lý, cần lập luậnCó nên can thiệp vào hệ sinh thái để cứu một loài?Một tiết học IB điển hình đi qua cả ba, theo đúng thứ tự đó. Phần lớn lớp học truyền thống dừng ở loại đầu tiên.</p><h3 id="cach-cham-theo-bon-tieu-chi-khong-theo-phan-tram-​" tabindex="-1">Cách chấm: theo bốn tiêu chí, không theo phần trăm <a href="#cach-cham-theo-bon-tieu-chi-khong-theo-phan-tram">​</a> <a class="header-anchor" href="#cach-cham-theo-bon-tieu-chi-khong-theo-phan-tram-​" aria-label="Permalink to &quot;Cách chấm: theo bốn tiêu chí, không theo phần trăm [​](#cach-cham-theo-bon-tieu-chi-khong-theo-phan-tram)&quot;">​</a></h3><p>Mỗi môn có bốn tiêu chí A–D, mỗi tiêu chí 0–8 điểm, và <strong>được chấm riêng</strong>. Một học sinh có thể mạnh ở &quot;điều tra&quot; (B) nhưng yếu ở &quot;trình bày&quot; (C) — điều mà một con số 7.5 chung sẽ che mất hoàn toàn. Cách chấm này khớp trực tiếp với <a href="/learner/learner-model">một nguyên tắc của Nemo12</a>: điểm trung bình che giấu thông tin cần thiết để giúp một đứa trẻ.</p><h2 id="đoc-demo-the-nao-cho-co-ich-​" tabindex="-1">Đọc demo thế nào cho có ích <a href="#đoc-demo-the-nao-cho-co-ich">​</a> <a class="header-anchor" href="#đoc-demo-the-nao-cho-co-ich-​" aria-label="Permalink to &quot;Đọc demo thế nào cho có ích [​](#đoc-demo-the-nao-cho-co-ich)&quot;">​</a></h2><p><strong>Chú ý các câu hỏi dẫn của giáo viên.</strong> Đây là phần khó nhất và cũng là phần bạn mượn được ngay. Chúng gần như không bao giờ là câu trả lời — chúng đẩy học sinh nghĩ thêm một bước. <strong>Chú ý khoảng lặng.</strong> Trong mọi demo đều có đoạn học sinh bế tắc mà giáo viên <strong>không cứu</strong>. Đó không phải sơ suất — đó là chỗ việc học xảy ra. <strong>Chú ý bước chốt lại.</strong> Inquiry mà không chốt sẽ để lại một lớp học tự tin với những kết luận sai. Mọi demo đều có bước này, và nó luôn dùng ngôn ngữ chính xác. Một điều nên biết trước Inquiry đòi hỏi học sinh <strong>đã có nền</strong>. Không ai khám phá được điều gì về thứ mình không biết gì cả. Trong các demo, luôn có phần &quot;cần biết trước&quot; — và bỏ qua phần đó là lý do phổ biến nhất khiến inquiry thất bại khi được áp dụng vội. <a href="/ideas/inquiry-based">Xem thêm →</a> IB không đặc biệt vì nó khó. Nó đặc biệt vì nó dành thời gian cho câu hỏi &quot;vì sao&quot; — và tính điểm cho câu trả lời của học sinh về câu hỏi đó.</p>',20)])])}const b=t(o,[["render",c]]);export{s as __pageData,b as default};
